 string flag,folder;bool failed,finished;readonly Stack<IEnumerator> stack=new Stack<IEnumerator>();readonly List<string> records=new List<string>();readonly List<float> samples=new List<float>();readonly List<Gamepad> pads=new List<Gamepad>();readonly Dictionary<string,string> prefs=new Dictionary<string,string>();Keyboard keyboard;InputSettings original,probe;AirHockeyMatch air;HockeyMatch ice;long memory;int gc;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Launch(){foreach(string flag in new[]{"-tsArenaUpdate","-tsAirAI","-tsAirCorner"})if(Array.IndexOf(Environment.GetCommandLineArgs(),flag)>=0){var g=new GameObject("Arena development validation");DontDestroyOnLoad(g);g.AddComponent<SportsArenaSmoke>().flag=flag;return;}}
 void Start(){folder=LWS.TruckSports.SportsEvidencePaths.Folder("ArenaSmoke");Directory.CreateDirectory(folder);foreach(string key in new[]{AirHockeyMatch.SetupKey,HockeyMatch.SetupKey,LWS.TruckBowling.BowlingMatch.SetupKey,LWS.TruckBilliards.BilliardsSession.SetupKey})prefs[key]=LWS.TruckSports.SportsPrefs.HasKey(key)?LWS.TruckSports.SportsPrefs.GetString(key):null;records.Add("Physical pads before injection: "+Gamepad.all.Count);original=InputSystem.settings;probe=Instantiate(original);probe.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=probe;keyboard=InputSystem.AddDevice<Keyboard>("Arena software keyboard");Application.logMessageReceived+=Log;UnityEngine.Random.InitState(4242);memory=GC.GetTotalMemory(false);gc=GC.CollectionCount(0);stack.Push(Run());}
 void Log(string text,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception){failed=true;records.Add("RUNTIME ERROR "+text);}}
 void Update(){if(finished)return;if(air!=null&&air.rules.Live&&!air.MenuOpen||ice!=null&&ice.rules.Live&&!ice.MenuOpen)samples.Add(Time.unscaledDeltaTime);try{while(stack.Count>0){var s=stack.Peek();if(!s.MoveNext()){stack.Pop();continue;}if(s.Current is IEnumerator nested){stack.Push(nested);continue;}return;}Finish(failed?2:0);}catch(Exception e){records.Add("FAIL "+e);Debug.LogError("ARENA_FAIL "+e);Finish(2);}}
 void Finish(int code){finished=true;foreach(var kv in prefs)if(kv.Value==null)LWS.TruckSports.SportsPrefs.DeleteKey(kv.Key);else LWS.TruckSports.SportsPrefs.SetString(kv.Key,kv.Value);LWS.TruckSports.SportsPrefs.Save();records.Add("GPU="+SystemInfo.graphicsDeviceName+" API="+SystemInfo.graphicsDeviceType+" resolution="+Screen.width+"x"+Screen.height+" timeScale="+Time.timeScale);if(samples.Count>0){samples.Sort();double total=0;foreach(float s in samples)total+=s;records.Add("PERF frames="+samples.Count+" meanMs="+(total/samples.Count*1000).ToString("F2")+" p95Ms="+(samples[(int)(samples.Count*.95)]*1000).ToString("F2")+" p99Ms="+(samples[(int)(samples.Count*.99)]*1000).ToString("F2")+" worstMs="+(samples[samples.Count-1]*1000).ToString("F2")+" managedDelta="+(GC.GetTotalMemory(false)-memory)+" GC0="+(GC.CollectionCount(0)-gc));}records.Add("RuntimeErrors="+(failed?1:0)+" ExitRequest="+code);File.WriteAllLines(Path.Combine(folder,"results.txt"),records);foreach(var p in pads)if(p.added)InputSystem.RemoveDevice(p);if(keyboard.added)InputSystem.RemoveDevice(keyboard);InputSystem.settings=original;Destroy(probe);Time.timeScale=1;Debug.Log("ARENA_FINISHED code="+code);Application.Quit(code);}
 void OnDestroy(){Application.logMessageReceived-=Log;}void Check(bool value,string text){if(!value)throw new Exception(text);records.Add("PASS "+text);Debug.Log("ARENA_PASS "+text);}void Keys(params Key[] keys){InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));}void Pad(Gamepad p,Vector2 left=default,Vector2 right=default,float gas=0,GamepadButton? button=null){if(p==null||!p.added||!p.enabled)return;var state=new GamepadState{leftStick=left,rightStick=right,rightTrigger=gas};if(button.HasValue)state=state.WithButton(button.Value);InputSystem.QueueStateEvent(p,state);}
 IEnumerator Delay(float seconds){float until=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<until)yield return null;}IEnumerator Wait(Func<bool> condition,float seconds,string text){float until=Time.realtimeSinceStartup+seconds;while(!condition()){if(Time.realtimeSinceStartup>until)throw new Exception("Timeout "+text+(air!=null?" phase="+air.rules.Phase+" puck="+air.puck.position+" scores="+air.rules.Score[0]+":"+air.rules.Score[1]+" trucks="+air.trucks[0].body.position+"/"+air.trucks[1].body.position+" targets="+air.agents[0].Target+"/"+air.agents[1].Target+" yaw="+air.trucks[1].transform.eulerAngles.y+" controls="+air.trucks[1].steer+"/"+air.trucks[1].throttle:""));yield return null;}}
