 void ParkIce(){Keys();for(int i=0;i<6;i++)ice.trucks[i].ResetBody(new Vector3(-10+i*4,.36f,5.5f),ice.SpawnRotation(i));ice.puck.position=new Vector3(0,.22f,-6);ice.puck.linearVelocity=Vector3.zero;Physics.SyncTransforms();}
 IEnumerator ThrottleLimits(){var g=new GameObject("Physical partial-throttle speed-limit fixture");var body=g.AddComponent<Rigidbody>();body.useGravity=false;body.constraints=RigidbodyConstraints.FreezeRotation;var drive=g.AddComponent<SportsThrottleLimitProbe>();drive.body=body;for(int i=0;i<3;i++){drive.air=i==1;drive.reverse=i==2;float limit=i==0?11:i==1?9:6;body.position=new Vector3(0,20,0);body.rotation=Quaternion.identity;body.linearVelocity=Vector3.forward*limit*(drive.reverse?-1:1);drive.opposing=false;yield return Delay(1);float speed=body.linearVelocity.magnitude;Check(speed<=limit+.4f,"partial throttle respects "+(i==0?"Ice drive":i==1?"Air drive":"reverse")+" limit speed="+speed.ToString("F2"));}Destroy(g);yield return null;}
