 IEnumerator Rounded(){ParkAir();var center=new Vector3(air.goalLine-air.cornerRadius,.22f,air.halfWidth-air.cornerRadius);air.puck.position=center+new Vector3(1,0,1).normalized*(air.cornerRadius-.2f-air.radius-.25f);air.puck.linearVelocity=new Vector3(7,0,7);int rail=air.puckContact.RailContacts;Physics.SyncTransforms();yield return Wait(()=>air.puckContact.RailContacts>rail,1,"physical curved corner contact");yield return Delay(.06f);Check(air.puck.linearVelocity.x< -2&&air.puck.linearVelocity.z< -2,"rounded corner deflects puck inward on both axes");ParkAir();var t=air.trucks[1];t.ResetBody(new Vector3(10,.36f,4),Quaternion.Euler(0,45,0));t.body.linearVelocity=new Vector3(6,0,6);Keys(Key.UpArrow);yield return Delay(.6f);Keys();Check(RoundedTruck(t),"entire moving rotated truck stays inside rounded rails");Capture("04-rounded-corners");yield return Delay(.1f);ParkAir();int before=air.Recoveries;air.puck.position=new Vector3(11.5f,.22f,5.5f);Physics.SyncTransforms();yield return Wait(()=>air.Recoveries>before,2,"puck outside cut-off corner recovers");Check(air.rules.Score[0]==0&&air.rules.Score[1]==0,"cut-corner recovery preserves score");yield return Wait(()=>air.rules.Live,4,"rounded recovery countdown");}
 bool RoundedTruck(AirHockeyTruck t){var q=t.body.rotation;for(int x=-1;x<=1;x+=2)for(int z=-1;z<=1;z+=2){var p=t.body.position+q*new Vector3(x*t.shape.size.x*.5f,0,z*t.shape.size.z*.5f);if(!AirHockeyArena.Contains(p,air.goalLine,air.halfWidth,air.cornerRadius,.1f))return false;}return true;}
 IEnumerator CornerOnly(){yield return StartAir(AirHockeyMode.PlayerAI);ParkAir();air.puck.position=AirHockeyArena.CornerPuck(air.goalLine,air.halfWidth,air.cornerRadius,air.radius,1,1);air.puck.linearVelocity=Vector3.zero;air.trucks[1].ResetBody(new Vector3(8,.36f,3),Quaternion.Euler(0,-90,0));Physics.SyncTransforms();int contact=air.puckContact.TruckContacts,recovery=air.Recoveries;var corner=air.puck.position;float until=Time.realtimeSinceStartup+18,next=0;while(Time.realtimeSinceStartup<until){if(Time.realtimeSinceStartup>next){next=Time.realtimeSinceStartup+1;var t=air.trucks[1];records.Add("CORNER puck="+air.puck.position+" truck="+t.body.position+" velocity="+t.body.linearVelocity+" yaw="+t.transform.eulerAngles.y+" target="+air.agents[1].Target+" gas="+t.throttle+" steer="+t.steer+" contacts="+air.puckContact.TruckContacts+" phase="+air.rules.Phase);File.WriteAllLines(Path.Combine(folder,"progress.txt"),records);Capture("corner-"+records.Count);}if(air.puckContact.TruckContacts>contact&&Vector3.Distance(air.puck.position,corner)>.8f)break;yield return null;}Check(air.puckContact.TruckContacts>contact&&Vector3.Distance(air.puck.position,corner)>.8f,"AI physically clears accessible corner");Check(air.Recoveries==recovery,"corner clear uses contact without faceoff");}
 void CheckRoundDuringMatch(int i){if(!RoundedTruck(air.trucks[i]))throw new Exception("AI crossed rounded rail "+i+" body="+air.trucks[i].body.position+" yaw="+air.trucks[i].body.rotation.eulerAngles.y);}
 IEnumerator AI(){air.Configure(AirHockeyMode.AIVsAI);air.players[0].name="Azure AI";air.players[1].name="Amber AI";air.players[0].difficulty=HockeyDifficulty.Hard;air.players[1].difficulty=HockeyDifficulty.Normal;float start=Time.realtimeSinceStartup;int contacts=0,rails=0;for(int round=0;round<2;round++){Check(air.StartMatch(round>0),"physical AI match/rematch "+round);int expected=round%2;Check(air.rules.Server==expected,"opening alternates "+round);yield return Delay(.2f);AirHUD();Capture("ai-live-"+round);int last=-1;float nextStatus=0;float until=Time.realtimeSinceStartup+900;while(air.rules.Phase!=AirHockeyPhase.Finished){if(Time.realtimeSinceStartup>until)throw new Exception("AI match timeout scores="+air.rules.Score[0]+":"+air.rules.Score[1]+" puck="+air.puck.position+" truck="+air.trucks[0].body.position+"/"+air.trucks[1].body.position);for(int i=0;i<2;i++){CheckRoundDuringMatch(i);var bounds=air.trucks[i].shape.bounds;if(i==0&&bounds.max.x>.05f||i==1&&bounds.min.x<-.05f)throw new Exception("AI escaped half "+i+" bounds="+bounds.min+"/"+bounds.max+" body="+air.trucks[i].body.position+" yaw="+air.trucks[i].body.rotation.eulerAngles.y+" velocity="+air.trucks[i].body.linearVelocity+" render="+air.trucks[i].transform.position);}if(air.rules.Goals!=last||Time.realtimeSinceStartup>nextStatus){nextStatus=Time.realtimeSinceStartup+10;last=air.rules.Goals;records.Add("MATCH "+round+" goals="+last+" score="+air.rules.Score[0]+":"+air.rules.Score[1]+" recoveries="+air.Recoveries+" physicalContacts="+air.puckContact.TruckContacts+" rails="+air.puckContact.RailContacts+" phase="+air.rules.Phase+" screen="+air.menus.Screen+" puck="+air.puck.position+" trucks="+air.trucks[0].body.position+"/"+air.trucks[1].body.position+" targets="+air.agents[0].Target+"/"+air.agents[1].Target+" hud="+air.menus.hud.activeInHierarchy);File.WriteAllLines(Path.Combine(folder,"progress.txt"),records);}yield return null;}Check(air.rules.Score[air.rules.Winner]==7&&air.puckContact.TruckContacts>contacts,"full physical first-to-7 match "+round);Check(air.players[0].name=="Azure AI"&&air.players[1].name=="Amber AI","rematch identity retained "+round);contacts=air.puckContact.TruckContacts;rails=air.puckContact.RailContacts;Capture("ai-result-"+round);yield return Delay(1);Check(air.menus.Screen==AirHockeyScreen.Result,"results remain "+round);}Check(contacts>10&&rails>5,"repeated real truck / rail contacts "+contacts+"/"+rails);records.Add("SUSTAINED two full matches elapsed="+(Time.realtimeSinceStartup-start).ToString("F1")+" timeScale=1; no score/puck velocity/actor placement injection");}
#endif
}
